function findStalePaths(md, existingFiles) {
  const seen = new Set();
  const out = [];
  for (const m of md.matchAll(/`(src\/[^`\s]*)`/g)) {
    const p = m[1];
    if (seen.has(p)) continue;
    seen.add(p);
    if (!existingFiles.includes(p)) out.push(p);
  }
  return out;
}

