function lintContextFile(md, maxLines) {
  const warnings = [];
  const lines = md.split("\n").filter((l) => l.trim());
  if (lines.length > maxLines) warnings.push("too-long");
  if (/AKIA[0-9A-Z]{16}|sk-[A-Za-z0-9]{20,}/.test(md)) warnings.push("secret");
  if (/best practices|clean code/i.test(md)) warnings.push("vague");
  return warnings;
}

