def resolve_imports(files, entry):
    out = []
    for line in files[entry].split("\n"):
        s = line.strip()
        if s.startswith("@") and s[1:] in files:
            out.extend(files[s[1:]].split("\n"))
            continue
        out.append(line)
    return "\n".join(out)

