def resolve_imports(files, entry):
    def expand(path, stack):
        out = []
        for line in files[path].split("\n"):
            s = line.strip()
            if s.startswith("@") and s[1:] in files:
                target = s[1:]
                if target not in stack:
                    out.extend(expand(target, stack + [target]))
                continue
            out.append(line)
        return out
    return "\n".join(expand(entry, [entry]))
